def swim_in_water(grid):
    n = len(grid)

    def possible(t):
        if grid[0][0] > t:
            return False
        seen, stack = {(0, 0)}, [(0, 0)]
        while stack:
            r, c = stack.pop()
            if (r, c) == (n - 1, n - 1):
                return True
            for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= a < n and 0 <= b < n and (a, b) not in seen and grid[a][b] <= t:
                    seen.add((a, b)); stack.append((a, b))
        return False

    lo, hi = 0, n * n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if possible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def swim_in_water(grid):
    n = len(grid)
    seen, heap, t = {(0, 0)}, [(grid[0][0], 0, 0)], 0
    while heap:
        h, r, c = heapq.heappop(heap)
        t = max(t, h)
        if (r, c) == (n - 1, n - 1):
            return t
        for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= a < n and 0 <= b < n and (a, b) not in seen:
                seen.add((a, b))
                heapq.heappush(heap, (grid[a][b], a, b))

def swim_in_water(grid):
    n = len(grid)
    where = [None] * (n * n)
    for r in range(n):
        for c in range(n):
            where[grid[r][c]] = (r, c)
    parent = list(range(n * n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for t in range(n * n):
        r, c = where[t]
        for a, b in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= a < n and 0 <= b < n and grid[a][b] <= t:
                parent[find(r * n + c)] = find(a * n + b)
        if find(0) == find(n * n - 1):
            return t
